import sys

def solve():
    input = sys.stdin.readline
    t_str = input().strip()
    if not t_str:
        return
    t = int(t_str)

    for _ in range(t):
        n = int(input())
        adj = [[] for _ in range(n + 1)]
        for _ in range(n - 1):
            u, v = map(int, input().split())
            adj[u].append(v)
            adj[v].append(u)

        k1 = int(input())
        x_list = list(map(int, input().split()))
        k2 = int(input())
        y_list = list(map(int, input().split()))

        x_set = set(x_list)
        y_set = set(y_list)

        def ask_a(node):
            print(f"A {node}")
            sys.stdout.flush()
            res = int(input())
            if res == -1:
                sys.exit(0)
            return res

        def ask_b(node):
            print(f"B {node}")
            sys.stdout.flush()
            res = int(input().strip())
            if res == -1:
                sys.exit(0
            return res

        found_common = None

        for x_node in x_list:
            y_label = ask_a(x_node)
            if y_label in y_set:
                found_common = x_node
                break

        if found_common is None:
            for y_node in y_list:
                x_label = ask_b(y_node)
                if x_label in x_set:
                    found_common = x_label
                    break

        if found_common is not None:
            print(f"C {found_common}")
        else:
            print("C -1")
        sys.stdout.flush()

if __name__ == "__main__":
    solve()
